/**
 * Generic optimizer
 *
 * Tasks: - Collect information (hasUnion, hasFilter, hasService) - Collect all statements in a list (for source
 * selection), do not collect SERVICE expressions - Collect all Join arguments and group them in the NJoin structure for
 * easier optimization (flatten)
 *
 * @author Andreas Schwarte
 */
public class GenericInfoOptimizer extends AbstractSimpleQueryModelVisitor<OptimizationException>
		implements FedXOptimizer {

	protected boolean hasFilter = false;
	protected boolean hasUnion = false;
	protected boolean hasPathExpr = false;
	protected boolean hasTripleRefExpr = false;
	protected List<Service> services = null;
	protected long limit = -1; // set to a positive number if the main query has a limit
	protected List<StatementPattern> stmts = new ArrayList<>();
	private Graph activeGraph;
	private boolean hasGraph;
	private final Map<StatementPattern, QueryRoot> graphProbes = new IdentityHashMap<>();
	private TupleExpr queryModel;
	private GraphSourceDelegation.Proof delegationProof;

	// internal helpers
	private boolean seenProjection = false; // whether the main projection has been visited

	protected final QueryInfo queryInfo;
	private List<Endpoint> members;

	public GenericInfoOptimizer(QueryInfo queryInfo) {
		super(true);
		this.queryInfo = queryInfo;
	}

	public GenericInfoOptimizer(QueryInfo queryInfo, List<Endpoint> members) {
		super(true);
		this.queryInfo = queryInfo;
		this.members = List.copyOf(members);
	}

	public boolean hasFilter() {
		return hasFilter;
	}

	public boolean hasUnion() {
		return hasUnion;
	}

	public boolean hasTripleRefExpr() {
		return hasTripleRefExpr;
	}

	public boolean hasPathExpression() {
		return hasPathExpr;
	}

	public List<StatementPattern> getStatements() {
		return stmts;
	}

	public boolean hasLimit() {
		return limit > 0;
	}

	public long getLimit() {
		return limit;
	}

	@Override
	public void optimize(TupleExpr tupleExpr) {
		queryModel = tupleExpr;
		delegationProof = null;

		try {
			tupleExpr.visit(this);
		} catch (RuntimeException e) {
			throw e;
		} catch (Exception e) {
			if (e instanceof InterruptedException) {
				Thread.currentThread().interrupt();
			}
			throw new RuntimeException(e);
		}

	}

	@Override
	public void meet(Union union) {
		hasUnion = true;
		super.meet(union);
	}

	@Override
	public void meet(Filter filter) {
		hasFilter = true;
		super.meet(filter);
	}

	@Override
	public void meet(Service service) {
		if (services == null) {
			services = new ArrayList<>();
		}
		services.add(service);
	}

	@Override
	public void meet(Join node) {

		/*
		 * Optimization task:
		 *
		 * - Replace joins with a TripleRef to TripleRefStatementPattern (recursively) - Collect all join arguments
		 * recursively and create the NJoin structure for easier join order optimization
		 */

		// conditionally based on config support RDF 1.2 triple terms
		if (queryInfo.getFederationContext().getConfig().isEnableTripleRefSupport()) {
			var newNode = OptimizerUtil.flattenTripleRefJoins(node, queryInfo);
			if (!(newNode instanceof Join)) {
				node.replaceWith(newNode);
				newNode.visit(this);
				return;
			}
		}

		NJoin newJoin = OptimizerUtil.flattenJoin(node, queryInfo);
		newJoin.visitChildren(this);

		node.replaceWith(newJoin);
	}

	@Override
	public void meet(LeftJoin node) throws OptimizationException {
		/**
		 * Wrap the left join in order to keep a reference to the query info object
		 */
		FedXLeftJoin join = new FedXLeftJoin(node, queryInfo);
		join.visitChildren(this);

		node.replaceWith(join);
	}

	@Override
	public void meet(ArbitraryLengthPath node) throws OptimizationException {

		FedXArbitraryLengthPath falp = new FedXArbitraryLengthPath(node, queryInfo);
		falp.visitChildren(this);

		node.replaceWith(falp);
		hasPathExpr = true;
	}

	@Override
	public void meet(Graph node) {
		hasGraph = true;
		Graph previous = activeGraph;
		FedXGraph graph = new FedXGraph(node, queryInfo);
		activeGraph = graph;
		graph.getArg().visit(this);
		activeGraph = previous;
		node.replaceWith(graph);
	}

	@Override
	public void meet(ZeroLengthPath node) {
		// Algebra-only optimizations do not require an initialized federation. Resolve the legacy constructor's
		// member snapshot only when a path actually needs source annotations.
		if (members == null) {
			members = List.copyOf(queryInfo.getFederationContext().getFederation().getMembers());
		}
		List<StatementSource> sources = members.stream()
				.map(member -> new StatementSource(member.getId(), StatementSourceType.REMOTE))
				.toList();
		node.replaceWith(
				new FedXZeroLengthPath(node.getScope(), node.getSubjectVar().clone(), node.getObjectVar().clone(),
						node.getContextVar() == null ? null : node.getContextVar().clone(), queryInfo, sources));
		hasPathExpr = true;
	}

	@Override
	public void meet(StatementPattern node) {
		collectStatement(node);
	}

	private void collectStatement(StatementPattern node) {
		stmts.add(node);
		if (activeGraph != null && node.getScope() == StatementPattern.Scope.DEFAULT_CONTEXTS) {
			var name = activeGraph.getGraphName().getValue();
			Var graph = Var.of("fedx_graph_probe_" + NodeFactory.getNextId(), name instanceof Resource ? name : null,
					true, name instanceof Resource);
			StatementPattern probe = new StatementPattern(
					StatementPattern.Scope.NAMED_CONTEXTS,
					node.getSubjectVar().clone(), node.getPredicateVar().clone(), node.getObjectVar().clone(),
					graph);
			graphProbes.put(node, new QueryRoot(probe));
		}
	}

	public boolean hasGraph() {
		return hasGraph;
	}

	/** Requires both mandatory active-graph origins and accounted source dependencies. */
	public boolean canDelegateGraphsToSingleSource() {
		return !hasGraph || graphDelegationProof().eligible();
	}

	static boolean hasMandatoryPositiveGraphBody(TupleExpr expression, String graphName) {
		return GraphSourceDelegation.mandatoryOrigin(expression);
	}

	private GraphSourceDelegation.Proof graphDelegationProof() {
		if (delegationProof == null) {
			delegationProof = GraphSourceDelegation.analyze(queryModel);
		}
		return delegationProof;
	}

	/** Detached physical-data probes required before excluding otherwise unaccounted federation members. */
	public List<StatementPattern> additionalGraphSourceSelectionPatterns() {
		if (!hasGraph || !graphDelegationProof().eligible()) {
			return List.of();
		}
		GraphSourceDelegation.Dependency dependency = graphDelegationProof().dependency();
		if (dependency == GraphSourceDelegation.Dependency.COVERED) {
			return List.of();
		}
		List<StatementPattern> patterns = new ArrayList<>();
		for (StatementPattern.Scope scope : StatementPattern.Scope.values()) {
			if (dependency == GraphSourceDelegation.Dependency.PHYSICAL_RDF) {
				patterns.add(dependencyPattern(scope, null, null));
			} else {
				patterns.add(dependencyPattern(scope, RDF.TYPE, RDF.PROPOSITION_FORM));
				patterns.add(dependencyPattern(scope, RDF.PROPOSITION_FORM_SUBJECT, null));
				patterns.add(dependencyPattern(scope, RDF.PROPOSITION_FORM_PREDICATE, null));
				patterns.add(dependencyPattern(scope, RDF.PROPOSITION_FORM_OBJECT, null));
			}
		}
		return patterns;
	}

	private static StatementPattern dependencyPattern(StatementPattern.Scope scope, IRI predicate, Value object) {
		String id = NodeFactory.getNextId();
		return new StatementPattern(scope, Var.of("dependency_subject_" + id),
				Var.of("dependency_predicate_" + id, predicate, predicate != null, predicate != null),
				Var.of("dependency_object_" + id, object, object != null, object != null),
				scope == StatementPattern.Scope.NAMED_CONTEXTS ? Var.of("dependency_context_" + id) : null);
	}

	public StatementPattern sourceSelectionPattern(StatementPattern node) {
		QueryRoot probe = graphProbes.get(node);
		return probe == null ? node : (StatementPattern) probe.getArg();
	}

	public boolean hasGraphProbe(StatementPattern node) {
		return graphProbes.containsKey(node);
	}

	public TupleExpr selectedGraphProbe(StatementPattern node) {
		return graphProbes.get(node).getArg();
	}

	@Override
	public void meet(Projection node) throws OptimizationException {
		seenProjection = true;
		super.meet(node);
	}

	@Override
	public void meet(Slice node) throws OptimizationException {
		// remember the limit of the main query (i.e. outside of a projection)
		if (!seenProjection) {
			limit = node.getLimit();
		}
		super.meet(node);
	}

	@Override
	public void meet(DescribeOperator node) throws OptimizationException {
		/*
		 * Replace with a FedX Describe Operator
		 */
		FederatedDescribeOperator newNode = new FederatedDescribeOperator(node.getArg(), queryInfo);
		newNode.visitChildren(this);

		node.replaceWith(newNode);
	}

	@Override
	public void meetOther(QueryModelNode node) throws OptimizationException {

		if (node instanceof TripleRefStatementPattern st) {
			hasTripleRefExpr = true;
			collectStatement(st);
		}

		super.meetOther(node);
	}

	public boolean hasService() {
		return services != null && !services.isEmpty();
	}

	public List<Service> getServices() {
		return services == null ? Collections.emptyList() : services;
	}
}
